using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates temporal motion-vector prediction (<c>use_ref_frame_mvs</c>) on a real eight-frame
/// non-error-resilient AV1/IVF clip (generated by aomenc with temporal motion vectors enabled): each
/// inter frame saves its motion field, later frames select up to three motion-field references, project
/// their fields by order-hint distances and add the projected vectors as prediction candidates. Every
/// decoded frame's luma and chroma must be exactly equal to dav1d's decoded output.
/// </summary>
public class Av1TemporalMvDecodeTests
{
    private const string ClipIvfBase64 =
        "";

    private static readonly string[] Dav1dLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1dUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1dVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ];

    [Fact]
    public void DecodeAllFrames_TemporalMvs_MatchDav1dExactly()
    {
        using MemoryStream stream = new(Convert.FromBase64String(ClipIvfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(8, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            Assert.Equal(Convert.FromBase64String(Dav1dLumaBase64[i]), frames[i].Luma.Samples);
            Assert.Equal(Convert.FromBase64String(Dav1dUBase64[i]), frames[i].ChromaU.Samples);
            Assert.Equal(Convert.FromBase64String(Dav1dVBase64[i]), frames[i].ChromaV.Samples);
        }
    }
}
